from heapq import heappop, heappush


def lease_trace(events: list[tuple]) -> tuple[list, dict]:
    if not isinstance(events, list):
        raise ValueError("events must be a list")

    results = []
    leases = {}
    expirations = []
    next_token = 1
    previous_time = None
    event_lengths = {"acquire": 5, "renew": 6, "release": 5}

    for event in events:
        if not isinstance(event, tuple) or not event:
            raise ValueError("each event must be a nonempty tuple")

        action = event[0]
        if not isinstance(action, str) or action not in event_lengths:
            raise ValueError("unknown event action")
        if len(event) != event_lengths[action]:
            raise ValueError("incorrect event length")

        time, key, owner = event[1:4]
        if type(time) is not int or time < 0:
            raise ValueError("time must be a nonnegative exact integer")
        if previous_time is not None and time < previous_time:
            raise ValueError("times must be nondecreasing")
        if not isinstance(key, str) or not isinstance(owner, str):
            raise ValueError("key and owner must be strings")

        if action == "acquire":
            ttl = event[4]
        else:
            token = event[4]
            if type(token) is not int or token <= 0:
                raise ValueError("token must be a positive exact integer")
            if action == "renew":
                ttl = event[5]

        if action in ("acquire", "renew"):
            if type(ttl) is not int or ttl < 0:
                raise ValueError("ttl must be a nonnegative exact integer")

        previous_time = time

        while expirations and expirations[0][0] <= time:
            expiry, expired_token, expired_key = heappop(expirations)
            current = leases.get(expired_key)
            if (
                current is not None
                and current[1] == expired_token
                and current[2] == expiry
            ):
                del leases[expired_key]

        if action == "acquire":
            if key in leases:
                results.append(None)
                continue

            assigned_token = next_token
            next_token += 1
            results.append(assigned_token)

            if ttl > 0:
                expiry = time + ttl
                leases[key] = (owner, assigned_token, expiry)
                heappush(expirations, (expiry, assigned_token, key))

        else:
            current = leases.get(key)
            matches = (
                current is not None
                and current[0] == owner
                and current[1] == token
            )
            results.append(matches)

            if not matches:
                continue

            if action == "release" or ttl == 0:
                del leases[key]
            else:
                expiry = time + ttl
                leases[key] = (owner, token, expiry)
                heappush(expirations, (expiry, token, key))

    return results, leases

