def ttl_lru(capacity: int, actions: list[tuple]) -> tuple[list, list]:
    if type(capacity) is not int or capacity < 0:
        raise ValueError("capacity must be a nonnegative exact integer")
    if not isinstance(actions, list):
        raise ValueError("actions must be a list")

    cache = OrderedDict()
    snapshots = []
    results = []
    previous_time = -1

    def expire(now):
        expired_keys = [
            key
            for key, (_, expiry) in cache.items()
            if expiry <= now
        ]
