import inspect

from lazybridge import Plan, Step


def _construct_plan_component(cls, fields):
    parameters = inspect.signature(cls).parameters
    accepts_keywords = any(
        parameter.kind == inspect.Parameter.VAR_KEYWORD
        for parameter in parameters.values()
    )
    normalized_names = {
        name.replace("_", "").lower(): name for name in parameters
    }
    values = {}
    variadic_values = []

    for aliases, value in fields:
        name = next((alias for alias in aliases if alias in parameters), None)
        if name is None:
            name = next(
                (
                    normalized_names[alias.replace("_", "").lower()]
                    for alias in aliases
                    if alias.replace("_", "").lower() in normalized_names
                ),
                None,
            )
        if name is None:
            if not accepts_keywords:
                raise TypeError(
                    f"{cls.__name__} has no public parameter for {aliases[0]!r}"
                )
            name = aliases[0]

        parameter = parameters.get(name)
        if parameter is not None and parameter.kind == inspect.Parameter.VAR_POSITIONAL:
            variadic_values.extend(value if isinstance(value, (list, tuple)) else [value])
        else:
            values[name] = value

    positional_values = []
    for name, parameter in parameters.items():
        if parameter.kind == inspect.Parameter.POSITIONAL_ONLY:
            if name in values:
                positional_values.append(values.pop(name))
            elif parameter.default is not inspect.Parameter.empty:
                positional_values.append(parameter.default)
            else:
                raise TypeError(f"Missing required parameter {name!r}")

    if variadic_values:
        for name, parameter in parameters.items():
            if parameter.kind == inspect.Parameter.POSITIONAL_OR_KEYWORD:
                if name in values:
                    positional_values.append(values.pop(name))
                elif parameter.default is not inspect.Parameter.empty:
                    positional_values.append(parameter.default)
                else:
                    raise TypeError(f"Missing required parameter {name!r}")
        positional_values.extend(variadic_values)

    return cls(*positional_values, **values)


