    initial: dict[str, int], commands: list[tuple]
) -> tuple[dict, list[bool]]:
    if not isinstance(initial, dict) or not isinstance(commands, list):
        raise ValueError("Expected a dictionary and a list of commands")

    for name, balance in initial.items():
        if not isinstance(name, str):
            raise ValueError("Account names must be strings")
        if type(balance) is not int or balance < 0:
            raise ValueError("Balances must be nonnegative exact integers")

    balances = dict(initial)
    frames: list[tuple[dict[str, int], bool]] = []
    commits: list[bool] = []

    for command in commands:
        if not isinstance(command, tuple) or not command:
            raise ValueError("Commands must be nonempty tuples")

        operation = command[0]
        if not isinstance(operation, str):
            raise ValueError("Command names must be strings")

        if operation in ("begin", "commit", "rollback"):
            if len(command) != 1:
                raise ValueError("Invalid command length")

            if operation == "begin":
                if frames and frames[-1][1]:
                    raise ValueError("Cannot begin within a failed frame")
                current = frames[-1][0] if frames else balances
                frames.append((current.copy(), False))
                continue

            if not frames:
                raise ValueError("Commit or rollback without begin")

            frame_balances, failed = frames.pop()
            if operation == "commit":
                commits.append(not failed)
                if not failed:
                    if frames:
                        frames[-1] = (frame_balances, frames[-1][1])
                    else:
                        balances = frame_balances
            continue

        if operation != "move" or len(command) != 4:
            raise ValueError("Unknown or malformed command")

        _, src, dst, amount = command
        if not isinstance(src, str) or not isinstance(dst, str):
            raise ValueError("Account names must be strings")
        if src not in balances or dst not in balances:
            raise ValueError("Both accounts must exist")
        if type(amount) is not int or amount < 0:
            raise ValueError("Amounts must be nonnegative exact integers")

        if frames and frames[-1][1]:
            continue
        if src == dst:
            continue

        current = frames[-1][0] if frames else balances
        if current[src] < amount:
            if frames:
                frames[-1] = (current, True)
            continue

        current[src] -= amount
        current[dst] += amount

    if frames:
        raise ValueError("Unbalanced transaction frames")

    return balances, commits

