    total: int,
    weights: list[int],
    caps: list[int],
    groups: list[str] | None = None,
) -> list[int]:
    if type(total) is not int or total < 0:
        raise ValueError("total must be a nonnegative integer")
    if not isinstance(weights, list) or not isinstance(caps, list):
        raise ValueError("weights and caps must be lists")
    if len(weights) != len(caps):
        raise ValueError("weights and caps must have equal lengths")
    if any(type(weight) is not int or weight < 0 for weight in weights):
        raise ValueError("weights must contain nonnegative integers")
    if any(type(cap) is not int or cap < 0 for cap in caps):
        raise ValueError("caps must contain nonnegative integers")

    if groups is not None:
        if not isinstance(groups, list) or len(groups) != len(weights):
            raise ValueError("groups must be a list with one label per bin")
        if any(not isinstance(label, str) for label in groups):
            raise ValueError("group labels must be strings")

    eligible_capacity = sum(
        cap for weight, cap in zip(weights, caps) if weight > 0
    )
    if eligible_capacity < total:
        raise ValueError("eligible capacity is less than total")

    def allocate(
        amount: int,
        bin_weights: list[int],
        bin_caps: list[int],
    ) -> list[int]:
        allocation = [0] * len(bin_weights)
        active = [
            i
            for i, weight in enumerate(bin_weights)
            if weight > 0 and bin_caps[i] > 0
        ]
        remaining = amount

        while remaining > 0:
            weight_sum = sum(bin_weights[i] for i in active)
            saturated = [
                i
                for i in active
                if remaining * bin_weights[i]
                >= (bin_caps[i] - allocation[i]) * weight_sum
            ]

            if saturated:
                for i in saturated:
                    available = bin_caps[i] - allocation[i]
                    allocation[i] += available
                    remaining -= available
                active = [
                    i for i in active if allocation[i] < bin_caps[i]
                ]
                continue

            remainders = []
            floor_sum = 0
            for i in active:
                floor_share, remainder = divmod(
                    remaining * bin_weights[i], weight_sum
                )
                allocation[i] += floor_share
                floor_sum += floor_share
                remainders.append((remainder, i))

            leftover = remaining - floor_sum
            remainders.sort(key=lambda item: (-item[0], item[1]))
            for _, i in remainders[:leftover]:
                allocation[i] += 1
            remaining = 0

