    # permits removing a nonnegative-cost cycle while using fewer discounts.
    # Thus a cheapest walk with the fewest edges never repeats such a state.
    hop_limit = min(hops, 2 * len(vertices) * (requirement_count + 1) - 1)
    discount_limit = min(discounts, (hop_limit + 1) // 2)

    current: dict[
        tuple[str, int, int, bool], tuple[int, tuple[str, ...]]
    ] = {(start, progress, 0, False): (0, (start,))}

    best: tuple[int, int, tuple[str, ...]] | None = None

    for edge_count in range(1, hop_limit + 1):
